&= (2)(3 \times 10^{26} \text{ atoms/m}^3)\sqrt{\frac{(5.73 \times 10^{-20} \text{ m}^2/\text{s})(30 \text{ min})(60 \text{ s/min})}{\pi}} \\
&= 3.44 \times 10^{18} \text{ atoms/m}^2
\end{aligned}
